   "titulo": "«Los bribones no cambian», dijo un ejecutivo de Deutsche Bank sobre André Esteves, de BTG",
   "resumen": "Correos electrónicos filtrados revelan una controversia interna en torno a uno de los principales clientes del banco alemán en Brasil.",
